CREATE TABLE "public"."votes" (
  "id"            bigint                   GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "user_id"       uuid,
  "definition_id" bigint,
  "example_id"    bigint,
  "value"         integer,
  "created_at"    timestamp with time zone DEFAULT now(),
  CONSTRAINT "check_target" CHECK ((((definition_id IS NOT NULL) AND (example_id IS NULL)) OR ((definition_id IS NULL) AND (example_id IS NOT NULL)))),
  CONSTRAINT "unique_def_vote" UNIQUE (user_id, definition_id),
  CONSTRAINT "unique_ex_vote" UNIQUE (user_id, example_id),
  CONSTRAINT "votes_definition_id_fkey" FOREIGN KEY (definition_id) REFERENCES public.definitions(id) ON DELETE CASCADE,
  CONSTRAINT "votes_example_id_fkey" FOREIGN KEY (example_id) REFERENCES public.examples(id) ON DELETE CASCADE,
  CONSTRAINT "votes_pkey" PRIMARY KEY (id),
  CONSTRAINT "votes_user_id_fkey" FOREIGN KEY (user_id) REFERENCES public.profiles(id),
  CONSTRAINT "votes_value_check" CHECK ((value = ANY (ARRAY['-1'::integer, 1])))
);

CREATE TRIGGER trigger_update_vote_counts
  AFTER INSERT OR DELETE OR UPDATE ON public.votes
  FOR EACH ROW
  EXECUTE FUNCTION public.handle_vote_update();

REVOKE ALL ON SEQUENCE "public"."votes_id_seq" FROM "anon";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."votes_id_seq" TO "anon";

REVOKE ALL ON SEQUENCE "public"."votes_id_seq" FROM "authenticated";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."votes_id_seq" TO "authenticated";

REVOKE ALL ON SEQUENCE "public"."votes_id_seq" FROM "postgres";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."votes_id_seq" TO "postgres";

REVOKE ALL ON SEQUENCE "public"."votes_id_seq" FROM "service_role";

GRANT SELECT, UPDATE, USAGE ON SEQUENCE "public"."votes_id_seq" TO "service_role";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."votes" TO "anon", "authenticated";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."votes" TO "service_role";

REVOKE ALL ON TABLE "public"."votes" FROM "postgres";

GRANT DELETE, INSERT, MAINTAIN, REFERENCES, SELECT, TRIGGER, TRUNCATE, UPDATE ON TABLE "public"."votes" TO "postgres";
